def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Long straight bars are endpoints. Markers project perpendicularly to
    # the nearest aligned bar; marker becomes 4 and intervening background
    # cells are filled with the marker's original color.
    bars=[]
    for r in range(h):
        c=0
        while c<w:
            v=grid[r][c]; j=c+1
            while j<w and grid[r][j]==v: j+=1
            if j-c>=3: bars.append(('h',r,c,j,v))
            c=j
    for c in range(w):
        r=0
        while r<h:
            v=grid[r][c]; j=r+1
            while j<h and grid[j][c]==v: j+=1
            if j-r>=3: bars.append(('v',c,r,j,v))
            r=j
    barcolors={b[4] for b in bars}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in barcolors: continue
            # Marker is a singleton non-background cell, pick bar orientation
            # along the axis perpendicular to its span.
            options=[]
            for typ,a,s,e,bcol in bars:
                if typ=='h' and s<=c<e and r not in range(s,e):
                    options.append((abs(r-a), 'v', a, bcol))
                elif typ=='v' and s<=r<e and c!=a:
                    options.append((abs(c-a), 'h', a, bcol))
            if not options: continue
            _,axis,anchor,bcol=min(options)
            out[r][c]=4
            if axis=='v':
                step=1 if anchor>r else -1
                for rr in range(r+step,anchor,step):
                    if grid[rr][c] not in barcolors: out[rr][c]=v
            else:
                step=1 if anchor>c else -1
                for cc in range(c+step,anchor,step):
                    if grid[r][cc] not in barcolors: out[r][cc]=v
    return out
PY
