    for r in range(h):
        c=0
        while c<w:
            v=grid[r][c]; j=c+1
            while j<w and grid[r][j]==v: j+=1
            if j-c>=3: bars.append(('h',r,c,j,v))
            c=j
    for c in range(w):
        r=0
        while r<h:
            v=grid[r][c]; j=r+1
            while j<h and grid[j][c]==v: j+=1
            if j-r>=3: bars.append(('v',c,r,j,v))
